/**
 * CLI Configuration structure
 */
export interface CliConfig {
    apiKey?: string;
    apiUrl?: string;
    teamId?: string;
    teamName?: string;
    userId?: string;
    installId?: string;
    telemetryNoticeShown?: boolean;
    /**
     * `config set generation.autoConfirmBelow N`: quotes costing ≤N credits
     * confirm without asking. 0/absent = always ask; hard-capped at 200
     * (AUTO_CONFIRM_MAX).
     */
    generationAutoConfirmBelow?: number;
}
/** Where the resolved API token came from. */
export type TokenSource = 'env' | 'config';
/**
 * Resolve the config directory path.
 *
 * Precedence (highest first):
 *   1. `SUPERDESIGN_CONFIG_DIR` env override - the escape hatch for read-only
 *      HOME sandboxes (e.g. Codex web Work Mode where HOME=/root is unwritable).
 *   2. `$XDG_CONFIG_HOME/superdesign` when XDG_CONFIG_HOME is set.
 *   3. `~/.superdesign` legacy default.
 *
 * Back-compat: when XDG_CONFIG_HOME is set but the XDG location has no config
 * yet while a legacy `~/.superdesign/config.json` DOES exist, the legacy path
 * keeps being used so existing installs are never silently orphaned.
 */
export declare function getConfigDir(): string;
/**
 * Get the config file path
 */
export declare function getConfigPath(): string;
/** Result of a config-directory writability probe. */
export interface ConfigDirProbe {
    ok: boolean;
    dir: string;
    /** Actionable message when `ok` is false; empty otherwise. */
    message: string;
}
/**
 * Ensure the resolved config dir exists and is writable, by creating it and
 * round-tripping a temp probe file. Used as a login preflight so an
 * authorization is NEVER consumed before the CLI knows it can persist the
 * resulting token. On failure the message names `SUPERDESIGN_CONFIG_DIR` as
 * the fix (deliberately no silent fallback to the workspace or /tmp).
 */
export declare function ensureConfigDirWritable(): ConfigDirProbe;
/**
 * Load configuration from disk
 */
export declare function loadConfig(): CliConfig;
/**
 * Save configuration to disk
 */
export declare function saveConfig(config: CliConfig): void;
/**
 * Update specific config values (merge with existing).
 *
 * NOTE: this still throws when the config dir is unwritable - the credential
 * save path relies on that to surface a real persistence failure. Telemetry
 * callers must degrade instead (see {@link getOrCreateInstallId}).
 */
export declare function updateConfig(updates: Partial<CliConfig>): CliConfig;
/**
 * Clear credentials while preserving installation-level settings
 */
export declare function clearConfig(): void;
/** Get the stable, privacy-safe anonymous installation identity. */
export declare function getOrCreateInstallId(): string;
/**
 * Resolve the API token and its source. The env var wins over the config file,
 * and when it is set no config file is required at all.
 */
export declare function resolveToken(): {
    token: string;
    source: TokenSource;
} | null;
/** Where the active token comes from, or `null` when unauthenticated. */
export declare function getTokenSource(): TokenSource | null;
/**
 * Check if user is authenticated (via env token or config)
 */
export declare function isAuthenticated(): boolean;
/**
 * Get API key or throw if not authenticated
 */
export declare function getApiKey(): string;
/**
 * Get the API URL (from config or default)
 */
export declare function getApiUrl(): string;
